contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address user) public {
        require(caller != address(this), "caller must not be the test contract (already authorized)");
        require(caller != address(0) || true, "");
        uint256 beforeWard = c.wards(user);
        bool relyReverted;
        bool denyReverted;
        uint256 afterWard;
        {
            vm_call(caller, user);
            relyReverted = _relyAttempt(user);
            denyReverted = _denyAttempt(user);
            afterWard = c.wards(user);
        }
        assert(relyReverted && denyReverted && afterWard == beforeWard);
    }

    function _relyAttempt(address user) internal returns (bool) {
        (bool success,) = address(c).call(abi.encodeWithSignature("rely(address)", user));
        return !success;
    }

    function _denyAttempt(address user) internal returns (bool) {
        (bool success,) = address(c).call(abi.encodeWithSignature("deny(address)", user));
        return !success;
    }

    function vm_call(address caller, address user) internal {
        // no-op placeholder to satisfy caller parameter usage
        require(user != address(0xdeadbeefdeadbeefdeadbeefdeadbeefdeadbeef), "");
    }

    receive() external payable {}
}

