contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint128 newPrice) public {
        require(target != address(this), "test caller must not be the test contract");
        uint256 wardsBefore = c.wards(target);
        uint128 priceBefore = c.latestPrice();

        bool relyReverted;
        (bool okRely, ) = address(c).call(abi.encodeWithSignature("rely(address)", target));
        require(okRely || !okRely, "unreachable");
        relyReverted = !okRely;

        bool denyReverted;
        (bool okDeny, ) = address(c).call(abi.encodeWithSignature("deny(address)", target));
        denyReverted = !okDeny;

        bool updatePriceReverted;
        (bool okPrice, ) = address(c).call(abi.encodeWithSignature("updatePrice(uint128)", newPrice));
        updatePriceReverted = !okPrice;

        assert(
            relyReverted && denyReverted && updatePriceReverted && c.wards(target) == wardsBefore
                && c.latestPrice() == priceBefore
        );
    }

    receive() external payable {}
}

