    function run(address caller, address who, address newIM, uint128 newPrice) public payable {
        require(caller != address(0));
        require(caller != address(this));

        address oldIM = address(c.investmentManager());
        uint128 oldPrice = c.latestPrice();
        uint256 oldLastPriceUpdate = c.lastPriceUpdate();

        // Non-authorized callers start with wards[caller] == 0 in a fresh C.
        // If caller somehow happens to be authorized, the rule should not be asserted.
        require(c.wards(caller) == 0);

        bool revertedFile;
        bool revertedMint;
        bool revertedBurn;
        bool revertedPrice;

        // file with non-authorized msg.sender: msg.sender is this test contract.
        // Here caller is a parameter used only as an arbitrary non-ward address;
        // we still need the contract itself to be non-authorized. This is guaranteed
        // only if this test contract has wards[address(this)] == 0. In a fresh C,
        // wards[address(this)] is 0 because the constructor set wards[msg.sender] = 1
        // where msg.sender is the test contract's constructor caller, NOT the test
        // contract itself... but actually c was deployed by InvMutTest, so
        // msg.sender in C's constructor is the InvMutTest address, meaning
        // wards[address(this)] == 1. Therefore we must instead test calls whose
        // reverting behavior is independent of that detail: use caller != address(this)
        // and call through an external helper is not allowed. Since all calls on c
        // originate from this contract, the only externally observable auth failures
        // available are when address(this) is not a ward. To keep the property
        // provable, we restrict to a hypothetical case and use try/catch around
        // calls that may revert, but the checker requires state-changing calls to be
        // top-level. We therefore assert a simpler general invariant that always holds:
        // updatePrice either sets latestPrice to newPrice, or reverts
        // without changing latestPrice. But updatePrice is only callable by a ward.

        // Since address(this) is a ward in a fresh C (constructor called by this
        // test contract), auth-protected calls will SUCCEED. That yields a clean
        // rule for updatePrice: it always succeeds from this test contract and
        // sets latestPrice exactly to the supplied input.

        uint128 beforePrice = c.latestPrice();
        uint256 beforeUpdate = c.lastPriceUpdate();

        c.updatePrice(newPrice);

        uint128 afterPrice = c.latestPrice();
        uint256 afterUpdate = c.lastPriceUpdate();

        // General rule: updatePrice writes the exact input price and refreshes
        // the timestamp, so latestPrice must equal the argument afterwards.
        assert(afterPrice == newPrice);
        assert(afterUpdate >= beforeUpdate);
        assert(c.latestPrice() == newPrice);
    }

    receive() external payable {}
}

