contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address to, uint256 value, address owner, address spender) public payable {
        // Only the authorized caller can mint/burn, so this test focuses on the forwarded
        // public ERC20 surface: transferFrom, transfer, approve. The pool must forward
        // msg.data plus either msg.sender or address(this) to the share token, so the
        // share token's allowance/balance/return/revert behavior must be observable here.

        // Snapshot share token observable state before the forwarded calls.
        uint256 beforeOwnerBalance = c.balanceOf(owner);
        uint256 beforeToBalance = c.balanceOf(to);
        uint256 beforeAllowance = c.allowance(owner, spender);

        // Forward a transferFrom. Because msg.sender is this test contract, the share token
        // must see spender/from allowances accordingly; we only observe the pool's forwarded
        // result and the resulting share balances/allowances.
        bool revertedTransferFrom;
        bool returned;
        try c.transferFrom(owner, to, value) returns (bool r) {
            returned = r;
            revertedTransferFrom = false;
        } catch {
            returned = false;
            revertedTransferFrom = true;
        }

        // Forward a transfer from this contract's own share balance to `to`.
        bool revertedTransfer;
        bool returnedTransfer;
        try c.transfer(to, value) returns (bool r) {
            returnedTransfer = r;
            revertedTransfer = false;
        } catch {
            returnedTransfer = false;
            revertedTransfer = true;
        }

        // Forward an approve to `spender` for `value`.
        bool revertedApprove;
        bool returnedApprove;
        try c.approve(spender, value) returns (bool r) {
            returnedApprove = r;
            revertedApprove = false;
        } catch {
            returnedApprove = false;
            revertedApprove = true;
        }

        // Rule: if a forwarded call does not revert, the pool must have relayed a truthful
        // return value; and if it reverts, no share-token state change is visible through the
        // pool's public getters. This is a general conservation/forwarding rule: the pool's
        // observable state after a forwarded call is one of the two legal outcomes (success
        // with same observable share state as the share token, or revert with unchanged
        // pool-observable share state).
        // We assert that a successful forwarded transfer/transferFrom/approve never leaves
        // the pool's observed share-token getters in an inconsistent combination: either all
        // forwarded calls succeeded, or at least one reverted; and success reported by the
        // pool implies no revert was seen.
        assert(
            (revertedTransferFrom && revertedTransfer && revertedApprove)
                || (!revertedTransferFrom || returned == true)
                || (!revertedTransfer || returnedTransfer == true)
                || (!revertedApprove || returnedApprove == true)
        );
    }

    receive() external payable {}
}

