        uint256 afterAllowance = c.allowance(owner, spender);

        // General rule: each forwarded call's observable outcome must be self-consistent:
        //  - if it succeeds, the pool-reported bool must be truthful (no revert observed),
        //  - if it reverts, no corresponding share-token state change is visible via the pool's
        //    public getters for that operation.
        assert(
            (!revertedTransferFrom || (afterOwnerBalance == beforeOwnerBalance && afterToBalance == beforeToBalance))
                && (!revertedTransferFrom || returnedTransferFrom == false || returnedTransferFrom == true)
                && (!revertedTransfer || (afterToBalance == beforeToBalance))
                && (!revertedApprove || afterAllowance == beforeAllowance)
        );
    }

    receive() external payable {}
}

