        // Ensure the attacker is not authorized, otherwise the rule is vacuous for this input.
        // The test contract itself is authorized after deploying c, so try to make the attacker
        // unauthorized through the public interface. If the attacker happens to be authorized
        // already, the precondition below will reject the input.
        require(c.wards(attacker) == 0, "precondition: attacker must not be authorized");

        uint256 beforeTarget = c.wards(target);

