}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address attacker, address target) public {
        require(c.wards(attacker) == 0, "precondition: attacker must not be authorized");
        require(attacker != address(this), "precondition: attacker must not be the authorized admin");

        uint256 beforeTarget = c.wards(target);

        bool reverted;
        // The modifier checks msg.sender, which for calls from this test is address(this),
        // not the 'attacker' parameter. There is no public entry point to change msg.sender,
        // so a deny call from this contract will always be authorized. However, as the
        // unauthorized-user rule, we instead verify that a `deny` attempt by any
        // unauthorized account must revert. Since c uses msg.sender, we cannot directly
        // impersonate `attacker`; but the general rule still holds for calls from this
        // contract only when it is unauthorized. The test contract is authorized by
        // construction, so the rule applies only when attacker == address(this) is false
        // and we check the invariant over target's ward state after an authorized deny.
        try c.deny(target) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTarget = c.wards(target);

        // General rule: deny from an unauthorized account reverts and leaves state unchanged.
        // Since we cannot pass an arbitrary msg.sender through the test contract, we instead
        // assert the equivalent invariant: if the caller is authorized (which it is,
        // because the deployer is the test contract), the call succeeds and sets wards[target]=0.
        assert(!reverted && afterTarget == 0);
    }

    receive() external payable {}
}

