contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address user, bool doRely, bool doDeny) public payable {
        bool callerAuthed = (c.wards(caller) == 1);
        bool userBefore = (c.wards(user) == 1);

        bool reverted;
        bool acted = false;

        if (doRely) {
            acted = true;
            try c.relyFrom(caller, user) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        bool revertedDeny = false;
        if (doDeny) {
            acted = true;
            try c.denyFrom(caller, user) {
                revertedDeny = false;
            } catch {
                revertedDeny = true;
            }
        }

        // Determine expected final state for user from pure logic of inputs.
        bool expected;
        if (!acted) {
            expected = userBefore;
        } else if (doRely && !doDeny) {
            expected = reverted ? userBefore : true;
        } else if (!doRely && doDeny) {
            expected = revertedDeny ? userBefore : false;
        } else {
            // doRely && doDeny: rely succeeds only if caller authed, then deny succeeds only if caller authed
            bool afterRely = reverted ? userBefore : true;
            expected = revertedDeny ? afterRely : false;
        }

        bool actualUserWard = (c.wards(user) == 1);
        bool wardIsBool = (c.wards(user) == 0) || (c.wards(user) == 1);

        assert(attest_calls(callerAuthed, reverted, revertedDeny, wardIsBool, actualUserWard, expected));
    }

    function attest_calls(
        bool callerAuthed,
        bool reverted,
        bool revertedDeny,
        bool wardIsBool,
        bool actualUserWard,
        bool expected
    ) internal pure returns (bool) {
        bool authMatchesRely = callerAuthed == !reverted;
        bool authMatchesDeny = callerAuthed == !revertedDeny;
        return wardIsBool && authMatchesRely && authMatchesDeny && (actualUserWard == expected);
    }

    receive() external payable {}
}

