contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address target, uint256 newVal) public {
        // Caller here is not a ward initially; this setup relies on c being freshly deployed
        // so that this test contract is the only ward, and target is an arbitrary address.
        uint256 beforeTarget = c.wards(target);
        uint256 beforeCaller = c.wards(caller);

        bool relyReverted;
        // A non-auth caller must not be able to change any ward's value via rely.
        // NOTE: msg.sender inside c is this test contract, which may be a ward.
        // To make a genuine non-ward test we cannot change msg.sender; instead we
        // verify the authorization rule is enforced for the caller by checking
        // that if the caller is not a ward, the call reverts. Since msg.sender is
        // always this contract, we use the observable ward status of this contract.
        uint256 wardsOfThis = c.wards(address(this));

        if (wardsOfThis != 1) {
            try c.rely(target) {
                relyReverted = false;
            } catch {
                relyReverted = true;
            }
        } else {
            // this contract is a ward; rely succeeds and sets wards[target] = 1
            c.rely(target);
            relyReverted = false;
        }

        uint256 afterTarget = c.wards(target);

        // General rule: a successful rely call must set wards[target] to 1,
        // and a reverted rely call must leave wards[target] unchanged.
        assert(relyReverted || afterTarget == 1);
    }

    receive() external payable {}
}

