contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address ward, address user, bool isRely) public payable {
        require(ward != address(0), "ward zero");
        require(user != address(0), "user zero");

        // The test contract is the deployer and thus a ward.
        c.rely(ward);

        uint256 before = c.wards(user);
        bool reverted;

        if (isRely) {
            try c.rely(user) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.deny(user) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterVal = c.wards(user);

        if (!reverted) {
            if (isRely) {
                assert(afterVal == 1 && c.wards(ward) == 1);
            } else {
                assert(afterVal == 0 && c.wards(ward) == 1);
            }
        } else {
            assert(afterVal == before && c.wards(ward) == 1);
        }
    }

    receive() external payable {}
}

