contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user, uint128 price, address data) public {
        require(user != address(this), "use a distinct non-contract user");

        bool callerIsWard = c.wards(address(this)) == 1;
        bool revertedRelyWard = false;
        bool revertedFileWard = false;
        bool revertedUpdatePriceWard = false;

        try c.rely(user) {
            revertedRelyWard = false;
        } catch {
            revertedRelyWard = true;
        }

        try c.file("investmentManager", data) {
            revertedFileWard = false;
        } catch {
            revertedFileWard = true;
        }

        try c.updatePrice(price) {
            revertedUpdatePriceWard = false;
        } catch {
            revertedUpdatePriceWard = true;
        }

        bool revertedRelyUser = false;
        bool revertedFileUser = false;
        bool revertedUpdatePriceUser = false;

        {
            address prevInvestmentManager = address(c.investmentManager());
            (bool ok, ) = address(c).call(abi.encodeWithSignature("rely(address)", user));
            revertedRelyUser = !ok;
            (ok, ) = address(c).call(abi.encodeWithSignature("file(bytes32,address)", bytes32("investmentManager"), data));
            revertedFileUser = !ok;
            (ok, ) = address(c).call(abi.encodeWithSignature("updatePrice(uint128)", price));
            revertedUpdatePriceUser = !ok;

            assert(
                callerIsWard && !revertedRelyWard && !revertedFileWard && !revertedUpdatePriceWard
                    && c.wards(user) == 1
                    && address(c.investmentManager()) == data
                    && c.latestPrice() == price
                    && revertedRelyUser && revertedFileUser && revertedUpdatePriceUser
                    && address(c.investmentManager()) == data
                    && c.latestPrice() == price
                    && prevInvestmentManager != address(0)
            );
        }
    }

    receive() external payable {}
}

